/* ---------- GAS dial geometry (plugin index.html: ring-tank.png channel walls) ---------- */
const CX=170, CY=170, A0=-135, A1=135, RNUM=150, RED=0.875;   // red zone = the last detent (8)
const ang = v => A0 + v*(A1-A0);
function pol(cx,cy,r,degCW){ const a=(degCW-90)*Math.PI/180; return [cx+r*Math.cos(a), cy+r*Math.sin(a)]; }
const CIN={x:166.69,y:158.45,r:91.89}, COUT={x:171.22,y:164.74,r:140.26};
function chanT(th,c){ const ux=Math.sin(th*Math.PI/180), uy=-Math.cos(th*Math.PI/180), dx=c.x-170, dy=c.y-170;
  const along=dx*ux+dy*uy, perp2=dx*dx+dy*dy-along*along; return along+Math.sqrt(Math.max(0,c.r*c.r-perp2)); }
function chanPath(v0,v1,roff=0){
  const a0=ang(v0), a1=ang(v1), n=Math.max(2,Math.ceil(Math.abs(a1-a0)/3)); let d='';
  for (let i=0;i<=n;i++){ const th=a0+(a1-a0)*i/n, t=(chanT(th,CIN)+chanT(th,COUT))/2+roff;
    const ux=Math.sin(th*Math.PI/180), uy=-Math.cos(th*Math.PI/180); d+=(i?'L':'M')+(170+t*ux).toFixed(2)+' '+(170+t*uy).toFixed(2)+' '; }
  return d;
}
// brass band of ring-tank.png, measured: outer rim = circle (170,170) r 167.6; the tube's outer wall = COUT.
// numPos = the middle of that band along the ray from the knob axis (the mount centre, 168.9,163).
const AXIS = {x:168.9, y:163}, RIM = {x:170, y:170, r:165};
function rayHit(th, c){ const ux=Math.sin(th*Math.PI/180), uy=-Math.cos(th*Math.PI/180), dx=AXIS.x-c.x, dy=AXIS.y-c.y;
  const b=dx*ux+dy*uy, q=dx*dx+dy*dy-c.r*c.r; return -b+Math.sqrt(Math.max(0,b*b-q)); }
