const PAL = { tube:{deep:'#8a5210',body:'#d9a03c',core:'#ffdf8e',glow:'#e8b054'},
  tape:{deep:'#0d6b40',body:'#3fd98a',core:'#b4ffd8',glow:'#4fe89a'}, fuzz:{deep:'#7a1408',body:'#ff3b28',core:'#ffb49c',glow:'#ff5a3a'} };
