    const tip=sm[sm.length-1], back=at(L-15); let ux=tip.x-back.x, uy=tip.y-back.y; const ul=Math.hypot(ux,uy)||1; ux/=ul; uy/=ul;
    const c1=P(tip.x-ux*18-uy*8.5, tip.y-uy*18+ux*8.5), c2=P(tip.x-ux*16.5+uy*7.2, tip.y-uy*16.5-ux*7.2), nt=P(tip.x-ux*11, tip.y-uy*11);
