['click','pointerdown','wheel'].forEach(ev => root.addEventListener(ev, e => { const n=stepFrom(e.target); if (n) markStep(n); }, true));
root.addEventListener('keydown', e => { if (e.key==='Enter'||e.key===' '||e.key.startsWith('Arrow')) { const n=stepFrom(e.target); if (n) markStep(n); } }, true);
