(document.fonts ? Promise.all(['17px "Gochi Hand"','19px "Permanent Marker"','700 16px Cinzel','27px VT323','500 11px Oswald','600 14px Oswald'].map(f => document.fonts.load(f).catch(() => null))).then(() => document.fonts.ready) : Promise.resolve()).then(() => { doFit(); drawArrows(true); });
let fitRaf = 0; new ResizeObserver(() => { cancelAnimationFrame(fitRaf); fitRaf = requestAnimationFrame(doFit); }).observe($('#wrap')); window.addEventListener('load', doFit);

